window.AUTH=window.AUTH||{};window.AUTH["13-352"]={"d":"13-352","id":"2014/13-352","n":"B&B Hardware Inc. v. Hargis Industries Inc.","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting petitioner","date":"2014-09-11","url":"https://www.justice.gov/osg/media/217316/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/bb-hardware-v-hargis-indus-amicus-merits","n":56}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep575/usrep575138/usrep575138.pdf","tr":true,"items":[{"t":"case","label":"American Heritage Life Ins. Co. v. Heritage Life Ins. Co.","cite":"494 F.2d 3","y":1974,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/494/3/","op":2,"by":{"0":"18"}},{"t":"case","label":"Astoria Fed. Sav. & Loan Ass’n v. Solimino","cite":"501 U.S. 104","y":1991,"id":"1990/89-1895","sc":1,"op":18,"ar":2,"sum":"Explaining that Utah Construction determined that “an administrative board's factfnding . . . could . . . have preclusive effect in an Article III suit raising damages claims over which the board had no jurisdiction”.","sumSrc":"opinion","by":{"0":"14, 16, 17, 18"}},{"t":"case","label":"B&B Hardware, Inc. v. Hargis Indus.","cite":"252 F.3d 1010","y":2001,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/252/1010/","by":{"0":"7"}},{"t":"case","label":"Bose Corp. v. QSC Audio Prods., Inc.","cite":"293 F.3d 1367","y":2002,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/293/1367/","by":{"0":"31"}},{"t":"case","label":"Bridgestone Ams. Tire Operations, LLC v. Federal Corp.","cite":"673 F.3d 1330","y":2012,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/673/1330/","by":{"0":"33"}},{"t":"case","label":"Delaware River Port Auth. v. Fraternal Order of Police","cite":"290 F.3d 567","y":2002,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/290/567/","op":1,"by":{"0":"24"}},{"t":"case","label":"Dr. Seuss Enters., L.P. v. Penguin Books USA, Inc.","cite":"109 F.3d 1394","y":1997,"url":"https://www.courtlistener.com/c/F.3d/109/1394/","by":{"0":"32"}},{"t":"case","label":"EZ Loader Boat Trailers, Inc. v. Cox Trailers, Inc.","cite":"746 F.2d 375","y":1984,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/746/375/","by":{"0":"18"}},{"t":"case","label":"Federated Dep’t Stores, Inc. v. Moitie","cite":"452 U.S. 394","y":1981,"id":"1980/79-1517","sc":1,"op":1,"sum":"Noting “the res judicata consequences of a fnal, unappealed judgment on the merits”.","sumSrc":"opinion","by":{"0":"15, 19, 30"}},{"t":"case","label":"Freedom Sav. & Loan Ass’n v. Way","cite":"757 F.2d 1176","y":1985,"url":"https://www.courtlistener.com/c/F.2d/757/1176/","by":{"0":"18, 19"}},{"t":"case","label":"Giant Food, Inc. v. Nation’s Foodservice, Inc.","cite":"710 F.2d 1565","y":1983,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/710/1565/","by":{"0":"20"}},{"t":"case","label":"Hayfield N. R.R. v. Chicago & N. W. Transp. Co.","cite":"467 U.S. 622","y":1984,"id":"1983/82-1579","sc":1,"op":1,"sum":"Appellant's proposed application of the Minnesota condemnation statute is not pre-empted by the Staggers Rail Act amendments to the Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"KP Permanent Make-Up, Inc. v. Lasting Impression I, Inc.","cite":"543 U.S. 111","y":2004,"id":"2004/03-409","sc":1,"sum":"The Court held that a party raising the classic defense of fair use did not need to negate any likelihood that the practice under question would confuse consumers about the origin of the goods. The Court interpreted federal trademark law as placing the burden of showing likelihood of confusion on the party charging infringement.","sumSrc":"Oyez","by":{"0":"3, 6"}},{"t":"case","label":"Kremer v. Chemical Constr. Corp.","cite":"456 U.S. 461","y":1982,"id":"1981/80-6045","sc":1,"op":1,"sum":"The District Court was required under 28 U. S. C. § 1738 to give preclusive effect to the state court decision upholding the state administrative agency's rejection of the employment discrimination claim.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Lambert Pharmacal Co. v. Bolton Chem. Corp.","cite":"219 F. 325","y":1915,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F./219/325/","by":{"0":"32, 33"}},{"t":"case","label":"Lambert Pharmacal Co. v. Mentho-Listine Chem. Co.","cite":"47 App. D.C. 197","y":1917,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/App.%20D.C./47/197/","by":{"0":"33"}},{"t":"case","label":"Leelanau Wine Cellars, Ltd. v. Black & Red, Inc.","cite":"502 F.3d 504","y":2007,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/502/504/","by":{"0":"20"}},{"t":"case","label":"Levi Strauss & Co. v. Abercrombie & Fitch Trading Co.","cite":"719 F.3d 1367","y":2013,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/719/1367/","by":{"0":"23"}},{"t":"case","label":"M2 Software, Inc. v. M2 Communications, Inc.","cite":"450 F.3d 1378","y":2006,"url":"https://www.courtlistener.com/c/F.3d/450/1378/","by":{"0":"5"}},{"t":"case","label":"Park ’N Fly, Inc. v. Dollar Park & Fly, Inc.","cite":"469 U.S. 189","y":1985,"id":"1984/83-1132","sc":1,"op":2,"sum":"Holding that an incontestable mark cannot be challenged as merely descriptive.","sumSrc":"opinion","by":{"0":"3"}},{"t":"case","label":"Planters Nut & Chocolate Co. v. Crown Nut Co., Inc.","cite":"305 F.2d 916","y":1962,"court":"C.C.P.A.","url":"https://www.courtlistener.com/c/F.2d/305/916/","by":{"0":"33"}},{"t":"case","label":"Qualitex Co. v. Jacobson Prods. Co., Inc.","cite":"514 U.S. 159","y":1995,"id":"1994/93-1577","sc":1,"sum":"The Lanham Act permits the registration of a trademark that consists, purely and simply, of a color.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34"}},{"t":"case","label":"Ring v. Arizona","cite":"536 U.S. 584","y":2002,"id":"2001/01-488","sc":1,"sum":"The Court held that, because Arizona's enumerated aggravating factors operates as \"the functional equivalent of an element of a greater offense,\" the Sixth Amendment requires that they be found by a jury.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Smith v. Bayer Corp.","cite":"131 S. Ct. 2368","y":2011,"id":"2010/09-1205","sc":1,"op":1,"sum":"The Court held that the federal court exceeded its authority under the relitigation exception to the Anti-Injunction Act when it prevented a group of plaintiffs from proceeding with a class-action lawsuit over a cholesterol-lowering drug.","sumSrc":"Oyez","by":{"0":"21, 22"}},{"t":"case","label":"SquirtCo v. Seven-Up Co.","cite":"628 F.2d 1086","y":1980,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/628/1086/","op":1,"by":{"0":"12"}},{"t":"case","label":"Taylor v. Sturgell","cite":"553 U.S. 880","y":2008,"id":"2007/07-371","sc":1,"sum":"Writing for a unanimous Court, Justice Ruth Bader Ginsburg held that such \"nonparty preclusion\" runs up against the \"deep-rooted historic tradition that everyone should have his own day in court.\" Virtual representation should only be applied rarely and under certain exceptions to the general rule, none of which the Court found applicable in this case.","sumSrc":"Oyez","by":{"0":"16, 20, 34"}},{"t":"case","label":"Two Pesos, Inc. v. Taco Cabana, Inc.","cite":"505 U.S. 763","y":1992,"id":"1991/91-971","sc":1,"sum":"The Supreme Court held that trade dress can be protected under the Lanham Act based on inherent distinctiveness even if there is no proof of a secondary meaning. Recovery is usually available for trademark infringement without a secondary meaning, and there is no persuasive reason for treating trade dress differently from other types of trademark.","sumSrc":"Oyez","by":{"0":"6"}},{"t":"case","label":"United States v. Stauffer Chem. Co.","cite":"464 U.S. 165","y":1984,"id":"1983/82-1448","sc":1,"op":1,"sum":"The Court held that the EPA's case against Stauffer was precluded by the doctrine of collateral estoppell.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"United States v. Utah Constr. & Mining Co.","cite":"384 U.S. 394","y":1966,"id":"1965/440","sc":1,"op":18,"sum":"The contract whereby respondent agreed to construct a facility for the Atomic knergy Commission contained a disputes clause which provided that \"all disputes concerning questions of fact arising under this contract\" should be decided by the contracting officer subject to written appeal to the head of the departrient, \"whose decision shall be final and conclusive upon the parties thereto.\" After completing the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 17, 18"}},{"t":"case","label":"University of Tenn. v. Elliott","cite":"478 U.S. 788","y":1986,"id":"1985/85-588","sc":1,"op":4,"sum":"When petitioner University of Tennessee informed respondent, a black employee, that he would be discharged for inadequate work performance and misconduct on the job, he requested an administrative hearing. Prior to the commencement of the administrative proceedings, respondent filed suit in Federal District Court against the University and others (also petitioners), alleging that his proposed discharge was racially …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 18, 21"}},{"t":"case","label":"Wal-Mart Stores, Inc. v. Samara Bros.","cite":"529 U.S. 205","y":2000,"id":"1999/99-150","sc":1,"sum":"The Court held that \"[i]n a section 43(a) action for infringement of unregistered trade dress, a product's design is distinctive, and therefore protectible, only upon a showing of secondary meaning.","sumSrc":"Oyez","by":{"0":"2"}},{"t":"case","label":"Case—Continued: Yamaha Int’l Corp. v. Hoshino Gakki Co.","cite":"840 F.2d 1572","y":1988,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/840/1572/","ar":1,"by":{"0":"4, 31"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["criminal-jury-venue","Criminal Jury and Venue Clause"],["treason","Treason Clause"],["treason-punishment","Punishment of Treason Clause"]],"by":{"0":"12"}},{"t":"usc","label":"15 U.S.C. § 1051","url":"https://www.law.cornell.edu/uscode/text/15/1051","subs":["(a)(1)","(a)(2)"],"stext":{"head":"§1051. Application for registration; verification","paras":[[0,"(a) Application for use of trademark"],[0,"(1) The owner of a trademark used in commerce may request registration of its trademark on the principal register hereby established by paying the prescribed fee and filing in the Patent and Trademark Office an application and a verified statement, in such form as may be prescribed by the Director, and such number of specimens or facsimiles of the mark as used as may be required by the Director."],[0,"(2) The application shall include specification of the applicant's domicile and citizenship, the date of the applicant's first use of the mark, the date of the applicant's first use of the mark in commerce, the goods in connection with which the mark is used, and a drawing of the mark."],[0,"(3) The statement shall be verified by the applicant and specify that—"],[1,"(A) the person making the verification believes that he or she, or the juristic person in whose behalf he or she makes the verification, to be the owner of the mark sought to be registered;"],[1,"(B) to the best of the verifier's knowledge and belief, the facts recited in the application are accurate;"],[1,"(C) the mark is in use in commerce; and"],[1,"(D) to the best of the verifier's knowledge and belief, no other person has the right to use such mark in commerce either in the identical form thereof or in such near resemblance thereto as to be likely, when used on or in connection with the goods of such other person, to cause confusion, or to cause mistake, or to deceive, except that, in the case of every application claiming concurrent use, the applicant shall—"],[2,"(i) state exceptions to the claim of exclusive use; and"],[2,"(ii) shall 1 specify, to the extent of the verifier's knowledge—"],[3,"(I) any concurrent use by others;"],[3,"(II) the goods on or in connection with which and the areas in which each concurrent use exists;"],[3,"(III) the periods of each use; and"],[3,"(IV) the goods and area for which the applicant desires registration."],[0,"(4) The applicant shall comply with such rules or regulations as may be prescribed by the Director. The Director shall promulgate rules prescribing the requirements for the application and for obtaining a filing date herein."],[0,"(b) Application for bona fide intention to use trademark"],[0,"(1) A person who has a bona fide intention, under circumstances showing the good faith of such person, to use a trademark in commerce may request registration of its trademark on the principal register hereby established by paying the prescribed fee and filing in the Patent and Trademark Office an application and a verified statement, in such form as may be prescribed by the Director."],[0,"(2) The application shall include specification of the applicant's domicile and citizenship, the goods in connection with which the applicant has a bona fide intention to use the mark, and a drawing of the mark."],[0,"(3) The statement shall be verified by the applicant and specify—"],[1,"(A) that the person making the verification believes that he or she, or the juristic person in whose behalf he or she makes the verification, to be entitled to use the mark in commerce;"],[1,"(B) the applicant's bona fide intention to use the mark in commerce;"],[1,"(C) that, to the best of the verifier's knowledge and belief, the facts recited in the application are accurate; and"],[1,"(D) that, to the best of the verifier's knowledge and belief, no other person has the right to use such mark in commerce either in the identical form thereof or in such near resemblance thereto as to be likely, when used on or in connection with the goods of such other person, to cause confusion, or to cause mistake, or to deceive."],[0,"Except for applications filed pursuant to section 1126 of this title, no mark shall be registered until the applicant has met the requirements of subsections (c) and (d) of this section."],[0,"(4) The applicant shall comply with such rules or regulations as may be prescribed by the Director. The Director shall promulgate rules prescribing the requirements for the application and for obtaining a filing date herein."],[0,"(c) Amendment of application under subsection (b) to conform to requirements of subsection (a)"],[0,"At any time during examination of an application filed under subsection (b), an applicant who has made use of the mark in commerce may claim the benefits of such use for purposes of this chapter, by amending his or her application to bring it into conformity with the requirements of subsection (a)."],[0,"(d) Verified statement that trademark is used in commerce"],[0,"(1) Within six months after the date on which the notice of allowance with respect to a mark is issued under section 1063(b)(2) of this title to an applicant under subsection (b) of this section, the applicant shall file in the Patent and Trademark Office, together with such number of specimens or facsimiles of the mark as used in commerce as may be required by the Director and payment of the prescribed fee, a verified statement that the mark is in use in commerce and specifying the date of the applicant's first use of the mark in commerce and those goods or services specified in the notice of allowance on or in connection with which the mark is used in commerce. Subject to examination and acceptance of the statement of use, the mark shall be registered in the Patent and Trademark Office, a certificate of registration shall be issued for those goods or services recited in the statement of use for which the mark is entitled to registration, and notice of registration shall be published in the Official Gazette of the Patent and Trademark Office. Such examination may include an examination of the factors set forth in subsections (a) through (e) of section 1052 of this title. The notice of registration shall specify the goods or services for which the mark is registered."],[0,"(2) The Director shall extend, for one additional 6-month period, the time for filing the statement of use under paragraph (1), upon written request of the applicant before the expiration of the 6-month period provided in paragraph (1). In addition to an extension under the preceding sentence, the Director may, upon a showing of good cause by the applicant, further extend the time for filing the statement of use under paragraph (1) for periods aggregating not more than 24 months, pursuant to written request of the applicant made before the expiration of the last extension granted under this paragraph. Any request for an extension under this paragraph shall be accompanied by a verified statement that the applicant has a continued bona fide intention to use the mark in commerce and specifying those goods or services identified in the notice of allowance on or in connection with which the applicant has a continued bona fide intention to use the mark in commerce. Any request for an extension under this paragraph shall be accompanied by payment of the prescribed fee. The Director shall issue regulations setting forth guidelines for determining what constitutes good cause for purposes of this paragraph."],[0,"(3) The Director shall notify any applicant who files a statement of use of the acceptance or refusal thereof and, if the statement of use is refused, the reasons for the refusal. An applicant may amend the statement of use."],[0,"(4) The failure to timely file a verified statement of use under paragraph (1) or an extension request under paragraph (2) shall result in abandonment of the application, unless it can be shown to the satisfaction of the Director that the delay in responding was unintentional, in which case the time for filing may be extended, but for a period not to exceed the period specified in paragraphs (1) and (2) for filing a statement of use."],[0,"(e) Designation of resident for service of process and notices"],[0,"If the applicant is not domiciled in the United States the applicant may designate, by a document filed in the United States Patent and Trademark Office, the name and address of a person resident in the United States on whom may be served notices or process in proceedings affecting the mark. Such notices or process may be served upon the person so designated by leaving with that person or mailing to that person a copy thereof at the address specified in the last designation so filed. If the person so designated cannot be found at the address given in the last designation, or if the registrant does not designate by a document filed in the United States Patent and Trademark Office the name and address of a person resident in the United States on whom may be served notices or process in proceedings affecting the mark, such notices or process may be served on the Director."],[0,"(f) Third-party submission of evidence"],[0,"A third party may submit for consideration for inclusion in the record of an application evidence relevant to a ground for refusal of registration. The third-party submission shall identify the ground for refusal and include a concise description of each piece of evidence submitted in support of each identified ground for refusal. Not later than 2 months after the date on which the submission is filed, the Director shall determine whether the evidence should be included in the record of the application. The Director shall establish by regulation appropriate procedures for the consideration of evidence submitted by a third party under this subsection and may prescribe a fee to accompany the submission. If the Director determines that the third-party evidence should be included in the record of the application, only the evidence and the ground for refusal to which the evidence relates may be so included. Any determination by the Director whether or not to include evidence in the record of an application shall be final and non-reviewable, and a determination to include or to not include evidence in the record shall not prejudice any party's right to raise any issue and rely on any evidence in any other proceeding."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1051?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1051. Application for registration; verification","tname":"Commerce and Trade","by":{"0":"2, 2, 2"}},{"t":"usc","label":"15 U.S.C. § 1052","url":"https://www.law.cornell.edu/uscode/text/15/1052","subs":["(d)","(e)(1)"],"stext":{"head":"§1052. Trademarks registrable on principal register; concurrent registration","paras":[[0,"No trademark by which the goods of the applicant may be distinguished from the goods of others shall be refused registration on the principal register on account of its nature unless it—"],[0,"(a) Consists of or comprises immoral, deceptive, or scandalous matter; or matter which may disparage or falsely suggest a connection with persons, living or dead, institutions, beliefs, or national symbols, or bring them into contempt, or disrepute; or a geographical indication which, when used on or in connection with wines or spirits, identifies a place other than the origin of the goods and is first used on or in connection with wines or spirits by the applicant on or after one year after the date on which the WTO Agreement (as defined in section 3501(9) of title 19) enters into force with respect to the United States."],[0,"(b) Consists of or comprises the flag or coat of arms or other insignia of the United States, or of any State or municipality, or of any foreign nation, or any simulation thereof."],[0,"(c) Consists of or comprises a name, portrait, or signature identifying a particular living individual except by his written consent, or the name, signature, or portrait of a deceased President of the United States during the life of his widow, if any, except by the written consent of the widow."],[0,"(d) Consists of or comprises a mark which so resembles a mark registered in the Patent and Trademark Office, or a mark or trade name previously used in the United States by another and not abandoned, as to be likely, when used on or in connection with the goods of the applicant, to cause confusion, or to cause mistake, or to deceive: Provided, That if the Director determines that confusion, mistake, or deception is not likely to result from the continued use by more than one person of the same or similar marks under conditions and limitations as to the mode or place of use of the marks or the goods on or in connection with which such marks are used, concurrent registrations may be issued to such persons when they have become entitled to use such marks as a result of their concurrent lawful use in commerce prior to (1) the earliest of the filing dates of the applications pending or of any registration issued under this chapter; (2) July 5, 1947, in the case of registrations previously issued under the Act of March 3, 1881, or February 20, 1905, and continuing in full force and effect on that date; or (3) July 5, 1947, in the case of applications filed under the Act of February 20, 1905, and registered after July 5, 1947. Use prior to the filing date of any pending application or a registration shall not be required when the owner of such application or registration consents to the grant of a concurrent registration to the applicant. Concurrent registrations may also be issued by the Director when a court of competent jurisdiction has finally determined that more than one person is entitled to use the same or similar marks in commerce. In issuing concurrent registrations, the Director shall prescribe conditions and limitations as to the mode or place of use of the mark or the goods on or in connection with which such mark is registered to the respective persons."],[0,"(e) Consists of a mark which (1) when used on or in connection with the goods of the applicant is merely descriptive or deceptively misdescriptive of them, (2) when used on or in connection with the goods of the applicant is primarily geographically descriptive of them, except as indications of regional origin may be registrable under section 1054 of this title, (3) when used on or in connection with the goods of the applicant is primarily geographically deceptively misdescriptive of them, (4) is primarily merely a surname, or (5) comprises any matter that, as a whole, is functional."],[0,"(f) Except as expressly excluded in subsections (a), (b), (c), (d), (e)(3), and (e)(5) of this section, nothing in this chapter shall prevent the registration of a mark used by the applicant which has become distinctive of the applicant's goods in commerce. The Director may accept as prima facie evidence that the mark has become distinctive, as used on or in connection with the applicant's goods in commerce, proof of substantially exclusive and continuous use thereof as a mark by the applicant in commerce for the five years before the date on which the claim of distinctiveness is made. Nothing in this section shall prevent the registration of a mark which, when used on or in connection with the goods of the applicant, is primarily geographically deceptively misdescriptive of them, and which became distinctive of the applicant's goods in commerce before December 8, 1993."],[0,"A mark which would be likely to cause dilution by blurring or dilution by tarnishment under section 1125(c) of this title, may be refused registration only pursuant to a proceeding brought under section 1063 of this title. A registration for a mark which would be likely to cause dilution by blurring or dilution by tarnishment under section 1125(c) of this title, may be canceled pursuant to a proceeding brought under either section 1064 of this title or section 1092 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1052?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1052. Trademarks registrable on principal register; concurrent registration","tname":"Commerce and Trade","by":{"0":"3, 3"}},{"t":"usc","label":"15 U.S.C. § 1057","url":"https://www.law.cornell.edu/uscode/text/15/1057","subs":["(b)"],"stext":{"head":"§1057. Certificates of registration","paras":[[0,"(a) Issuance and form"],[0,"Certificates of registration of marks registered upon the principal register shall be issued in the name of the United States of America, under the seal of the United States Patent and Trademark Office, and shall be signed by the Director or have his signature placed thereon, and a record thereof shall be kept in the United States Patent and Trademark Office. The registration shall reproduce the mark, and state that the mark is registered on the principal register under this chapter, the date of the first use of the mark, the date of the first use of the mark in commerce, the particular goods or services for which it is registered, the number and date of the registration, the term thereof, the date on which the application for registration was received in the United States Patent and Trademark Office, and any conditions and limitations that may be imposed in the registration."],[0,"(b) Certificate as prima facie evidence"],[0,"A certificate of registration of a mark upon the principal register provided by this chapter shall be prima facie evidence of the validity of the registered mark and of the registration of the mark, of the owner's ownership of the mark, and of the owner's exclusive right to use the registered mark in commerce on or in connection with the goods or services specified in the certificate, subject to any conditions or limitations stated in the certificate."],[0,"(c) Application to register mark considered constructive use"],[0,"Contingent on the registration of a mark on the principal register provided by this chapter, the filing of the application to register such mark shall constitute constructive use of the mark, conferring a right of priority, nationwide in effect, on or in connection with the goods or services specified in the registration against any other person except for a person whose mark has not been abandoned and who, prior to such filing—"],[1,"(1) has used the mark;"],[1,"(2) has filed an application to register the mark which is pending or has resulted in registration of the mark; or"],[1,"(3) has filed a foreign application to register the mark on the basis of which he or she has acquired a right of priority, and timely files an application under section 1126(d) of this title to register the mark which is pending or has resulted in registration of the mark."],[0,"(d) Issuance to assignee"],[0,"A certificate of registration of a mark may be issued to the assignee of the applicant, but the assignment must first be recorded in the United States Patent and Trademark Office. In case of change of ownership the Director shall, at the request of the owner and upon a proper showing and the payment of the prescribed fee, issue to such assignee a new certificate of registration of the said mark in the name of such assignee, and for the unexpired part of the original period."],[0,"(e) Surrender, cancellation, or amendment by owner"],[0,"Upon application of the owner the Director may permit any registration to be surrendered for cancellation, and upon cancellation appropriate entry shall be made in the records of the United States Patent and Trademark Office. Upon application of the owner and payment of the prescribed fee, the Director for good cause may permit any registration to be amended or to be disclaimed in part: Provided, That the amendment or disclaimer does not alter materially the character of the mark. Appropriate entry shall be made in the records of the United States Patent and Trademark Office and upon the certificate of registration."],[0,"(f) Copies of United States Patent and Trademark Office records as evidence"],[0,"Copies of any records, books, papers, or drawings belonging to the United States Patent and Trademark Office relating to marks, and copies of registrations, when authenticated by the seal of the United States Patent and Trademark Office and certified by the Director, or in his name by an employee of the Office duly designated by the Director, shall be evidence in all cases wherein the originals would be evidence; and any person making application therefor and paying the prescribed fee shall have such copies."],[0,"(g) Correction of United States Patent and Trademark Office mistake"],[0,"Whenever a material mistake in a registration, incurred through the fault of the United States Patent and Trademark Office, is clearly disclosed by the records of the Office a certificate stating the fact and nature of such mistake shall be issued without charge and recorded and a printed copy thereof shall be attached to each printed copy of the registration and such corrected registration shall thereafter have the same effect as if the same had been originally issued in such corrected form, or in the discretion of the Director a new certificate of registration may be issued without charge. All certificates of correction heretofore issued in accordance with the rules of the United States Patent and Trademark Office and the registrations to which they are attached shall have the same force and effect as if such certificates and their issue had been specifically authorized by statute."],[0,"(h) Correction of applicant's mistake"],[0,"Whenever a mistake has been made in a registration and a showing has been made that such mistake occurred in good faith through the fault of the applicant, the Director is authorized to issue a certificate of correction or, in his discretion, a new certificate upon the payment of the prescribed fee: Provided, That the correction does not involve such changes in the registration as to require republication of the mark."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1057?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1057. Certificates of registration","tname":"Commerce and Trade","by":{"0":"3"}},{"t":"usc","label":"15 U.S.C. § 1062","url":"https://www.law.cornell.edu/uscode/text/15/1062","subs":["(a)"],"stext":{"head":"§1062. Publication","paras":[[0,"(a) Examination and publication"],[0,"Upon the filing of an application for registration and payment of the prescribed fee, the Director shall refer the application to the examiner in charge of the registration of marks, who shall cause an examination to be made and, if on such examination it shall appear that the applicant is entitled to registration, or would be entitled to registration upon the acceptance of the statement of use required by section 1051(d) of this title, the Director shall cause the mark to be published in the Official Gazette of the Patent and Trademark Office: Provided, That in the case of an applicant claiming concurrent use, or in the case of an application to be placed in an interference as provided for in section 1066 of this title the mark, if otherwise registrable, may be published subject to the determination of the rights of the parties to such proceedings."],[0,"(b) Refusal of registration; amendment of application; abandonment; extensions of time to respond"],[0,"(1) If the applicant is found not entitled to registration, the examiner shall notify the applicant thereof and of the reasons therefor. The applicant may reply or amend the application, which shall then be reexamined. This procedure may be repeated until the examiner finally refuses registration of the mark or the application is abandoned as described in paragraph (2)."],[0,"(2) After notification under paragraph (1), the applicant shall have a period of 6 months in which to reply or amend the application, or such shorter time that is not less than 60 days, as prescribed by the Director by regulation. If the applicant fails to reply or amend or appeal within the relevant time period, including any extension under paragraph (3), the application shall be deemed to have been abandoned, unless it can be shown to the satisfaction of the Director that the delay in responding was unintentional, in which case the application may be revived and such time may be extended. The Director may prescribe a fee to accompany any request to revive."],[0,"(3) The Director shall provide, by regulation, for extensions of time to respond to the examiner for any time period under paragraph (2) that is less than 6 months. The Director shall allow the applicant to obtain extensions of time to reply or amend aggregating 6 months from the date of notification under paragraph (1) when the applicant so requests. However, the Director may set by regulation the time for individual periods of extension, and prescribe a fee, by regulation, for any extension request. Any request for extension shall be filed on or before the date on which a reply or amendment is due under paragraph (1)."],[0,"(c) Republication of marks registered under prior acts"],[0,"A registrant of a mark registered under the provisions of the Act of March 3, 1881, or the Act of February 20, 1905, may, at any time prior to the expiration of the registration thereof, upon the payment of the prescribed fee file with the Director an affidavit setting forth those goods stated in the registration on which said mark is in use in commerce and that the registrant claims the benefits of this chapter for said mark. The Director shall publish notice thereof with a reproduction of said mark in the Official Gazette, and notify the registrant of such publication and of the requirement for the affidavit of use or nonuse as provided for in subsection (b) of section 1058 of this title. Marks published under this subsection shall not be subject to the provisions of section 1063 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1062?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1062. Publication","tname":"Commerce and Trade","by":{"0":"3"}},{"t":"usc","label":"15 U.S.C. § 1063","url":"https://www.law.cornell.edu/uscode/text/15/1063","subs":["(a)"],"stext":{"head":"§1063. Opposition to registration","paras":[[0,"(a) Any person who believes that he would be damaged by the registration of a mark upon the principal register, including the registration of any mark which would be likely to cause dilution by blurring or dilution by tarnishment under section 1125(c) of this title, may, upon payment of the prescribed fee, file an opposition in the Patent and Trademark Office, stating the grounds therefor, within thirty days after the publication under subsection (a) of section 1062 of this title of the mark sought to be registered. Upon written request prior to the expiration of the thirty-day period, the time for filing opposition shall be extended for an additional thirty days, and further extensions of time for filing opposition may be granted by the Director for good cause when requested prior to the expiration of an extension. The Director shall notify the applicant of each extension of the time for filing opposition. An opposition may be amended under such conditions as may be prescribed by the Director."],[0,"(b) Unless registration is successfully opposed—"],[1,"(1) a mark entitled to registration on the principal register based on an application filed under section 1051(a) of this title or pursuant to section 1126 of this title shall be registered in the Patent and Trademark Office, a certificate of registration shall be issued, and notice of the registration shall be published in the Official Gazette of the Patent and Trademark Office; or"],[1,"(2) a notice of allowance shall be issued to the applicant if the applicant applied for registration under section 1051(b) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1063?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1063. Opposition to registration","tname":"Commerce and Trade","by":{"0":"4"}},{"t":"usc","label":"315 U.S.C. § 1064","url":"https://www.law.cornell.edu/uscode/text/315/1064","subs":["(1)"],"by":{"0":"8"}},{"t":"usc","label":"15 U.S.C. § 1064","url":"https://www.law.cornell.edu/uscode/text/15/1064","subs":["(3)"],"by":{"0":"8"}},{"t":"usc","label":"15 U.S.C. § 1065","url":"https://www.law.cornell.edu/uscode/text/15/1065","stext":{"head":"§1065. Incontestability of right to use mark under certain conditions","paras":[[0,"Except on a ground for which application to cancel may be filed at any time under paragraphs (3), (5), and (6) of section 1064 of this title, and except to the extent, if any, to which the use of a mark registered on the principal register infringes a valid right acquired under the law of any State or Territory by use of a mark or trade name continuing from a date prior to the date of registration under this chapter of such registered mark, the right of the owner to use such registered mark in commerce for the goods or services on or in connection with which such registered mark has been in continuous use for five consecutive years subsequent to the date of such registration and is still in use in commerce, shall be incontestable: Provided, That—"],[1,"(1) there has been no final decision adverse to the owner's claim of ownership of such mark for such goods or services, or to the owner's right to register the same or to keep the same on the register; and"],[1,"(2) there is no proceeding involving said rights pending in the United States Patent and Trademark Office or in a court and not finally disposed of; and"],[1,"(3) an affidavit is filed with the Director within one year after the expiration of any such five-year period setting forth those goods or services stated in the registration on or in connection with which such mark has been in continuous use for such five consecutive years and is still in use in commerce, and other matters specified in paragraphs (1) and (2) hereof; and"],[1,"(4) no incontestable right shall be acquired in a mark which is the generic name for the goods or services or a portion thereof, for which it is registered."],[0,"Subject to the conditions above specified in this section, the incontestable right with reference to a mark registered under this chapter shall apply to a mark registered under the Act of March 3, 1881, or the Act of February 20, 1905, upon the filing of the required affidavit with the Director within one year after the expiration of any period of five consecutive years after the date of publication of a mark under the provisions of subsection (c) of section 1062 of this title."],[0,"The Director shall notify any registrant who files the above-prescribed affidavit of the filing thereof."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1065?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1065. Incontestability of right to use mark under certain conditions","tname":"Commerce and Trade","by":{"0":"1"}},{"t":"usc","label":"15 U.S.C. § 1067","url":"https://www.law.cornell.edu/uscode/text/15/1067","subs":["(a)"],"stext":{"head":"§1067. Interference, opposition, and proceedings for concurrent use registration or for cancellation; notice; Trademark Trial and Appeal Board","paras":[[0,"(a) In every case of interference, opposition to registration, application to register as a lawful concurrent user, or application to cancel the registration of a mark, the Director shall give notice to all parties and shall direct a Trademark Trial and Appeal Board to determine and decide the respective rights of registration."],[0,"(b) The Trademark Trial and Appeal Board shall include the Director, Deputy 1 Director of the United States Patent and Trademark Office 2 the Commissioner for Patents, the Commissioner for Trademarks, and administrative trademark judges who are appointed by the Secretary of Commerce, in consultation with the Director."],[0,"(c) Authority of the Secretary.—The Secretary of Commerce may, in his or her discretion, deem the appointment of an administrative trademark judge who, before August 12, 2008, held office pursuant to an appointment by the Director to take effect on the date on which the Director initially appointed the administrative trademark judge."],[0,"(d) Defense to Challenge of Appointment.—It shall be a defense to a challenge to the appointment of an administrative trademark judge on the basis of the judge's having been originally appointed by the Director that the administrative trademark judge so appointed was acting as a de facto officer."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1067?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1067. Interference, opposition, and proceedings for concurrent use registration or for cancellation; notice; Trademark Trial and Appeal Board","tname":"Commerce and Trade","by":{"0":"1, 4"}},{"t":"usc","label":"15 U.S.C. § 1071","url":"https://www.law.cornell.edu/uscode/text/15/1071","subs":["(a)","(b)"],"stext":{"head":"§1071. Appeal to courts","paras":[[0,"(a) Persons entitled to appeal; United States Court of Appeals for the Federal Circuit; waiver of civil action; election of civil action by adverse party; procedure"],[0,"(1) An applicant for registration of a mark, party to an interference proceeding, party to an opposition proceeding, party to an application to register as a lawful concurrent user, party to a cancellation proceeding, a registrant who has filed an affidavit as provided in section 1058 of this title or section 1141k of this title, an applicant for renewal, or a registrant subject to an ex parte expungement proceeding or an ex parte reexamination proceeding, who is dissatisfied with the decision of the Director or Trademark Trial and Appeal Board, may appeal to the United States Court of Appeals for the Federal Circuit thereby waiving his right to proceed under subsection (b) of this section: Provided, That such appeal shall be dismissed if any adverse party to the proceeding, other than the Director, shall, within twenty days after the appellant has filed notice of appeal according to paragraph (2) of this subsection, files notice with the Director that he elects to have all further proceedings conducted as provided in subsection (b) of this section. Thereupon the appellant shall have thirty days thereafter within which to file a civil action under subsection (b) of this section, in default of which the decision appealed from shall govern the further proceedings in the case."],[0,"(2) When an appeal is taken to the United States Court of Appeals for the Federal Circuit, the appellant shall file in the United States Patent and Trademark Office a written notice of appeal directed to the Director, within such time after the date of the decision from which the appeal is taken as the Director prescribes, but in no case less than 60 days after that date."],[0,"(3) The Director shall transmit to the United States Court of Appeals for the Federal Circuit a certified list of the documents comprising the record in the United States Patent and Trademark Office. The court may request that the Director forward the original or certified copies of such documents during pendency of the appeal. In an ex parte case, the Director shall submit to that court a brief explaining the grounds for the decision of the United States Patent and Trademark Office, addressing all the issues involved in the appeal. The court shall, before hearing an appeal, give notice of the time and place of the hearing to the Director and the parties in the appeal."],[0,"(4) The United States Court of Appeals for the Federal Circuit shall review the decision from which the appeal is taken on the record before the United States Patent and Trademark Office. Upon its determination the court shall issue its mandate and opinion to the Director, which shall be entered of record in the United States Patent and Trademark Office and shall govern the further proceedings in the case. However, no final judgment shall be entered in favor of an applicant under section 1051(b) of this title before the mark is registered, if such applicant cannot prevail without establishing constructive use pursuant to section 1057(c) of this title."],[0,"(b) Civil action; persons entitled to; jurisdiction of court; status of Director; procedure"],[0,"(1) Whenever a person authorized by subsection (a) of this section to appeal to the United States Court of Appeals for the Federal Circuit, except for a registrant subject to an ex parte expungement proceeding or an ex parte reexamination proceeding, is dissatisfied with the decision of the Director or Trademark Trial and Appeal Board, said person may, unless appeal has been taken to said United States Court of Appeals for the Federal Circuit, have remedy by a civil action if commenced within such time after such decision, not less than sixty days, as the Director appoints or as provided in subsection (a) of this section. The court may adjudge that an applicant is entitled to a registration upon the application involved, that a registration involved should be canceled, or such other matter as the issues in the proceeding require, as the facts in the case may appear. Such adjudication shall authorize the Director to take any necessary action, upon compliance with the requirements of law. However, no final judgment shall be entered in favor of an applicant under section 1051(b) of this title before the mark is registered, if such applicant cannot prevail without establishing constructive use pursuant to section 1057(c) of this title."],[0,"(2) The Director shall not be made a party to an inter partes proceeding under this subsection, but he shall be notified of the filing of the complaint by the clerk of the court in which it is filed and shall have the right to intervene in the action."],[0,"(3) In any case where there is no adverse party, a copy of the complaint shall be served on the Director, and, unless the court finds the expenses to be unreasonable, all the expenses of the proceeding shall be paid by the party bringing the case, whether the final decision is in favor of such party or not. In suits brought hereunder, the record in the United States Patent and Trademark Office shall be admitted on motion of any party, upon such terms and conditions as to costs, expenses, and the further cross-examination of the witnesses as the court imposes, without prejudice to the right of any party to take further testimony. The testimony and exhibits of the record in the United States Patent and Trademark Office, when admitted, shall have the same effect as if originally taken and produced in the suit."],[0,"(4) Where there is an adverse party, such suit may be instituted against the party in interest as shown by the records of the United States Patent and Trademark Office at the time of the decision complained of, but any party in interest may become a party to the action. If there are adverse parties residing in a plurality of districts not embraced within the same State, or an adverse party residing in a foreign country, the United States District Court for the Eastern District of Virginia shall have jurisdiction and may issue summons against the adverse parties directed to the marshal of any district in which any adverse party resides. Summons against adverse parties residing in foreign countries may be served by publication or otherwise as the court directs."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1071?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1071. Appeal to courts","tname":"Commerce and Trade","by":{"0":"3, 3"}},{"t":"usc","label":"15 U.S.C. § 1072","url":"https://www.law.cornell.edu/uscode/text/15/1072","stext":{"head":"§1072. Registration as constructive notice of claim of ownership","paras":[[0,"Registration of a mark on the principal register provided by this chapter or under the Act of March 3, 1881, or the Act of February 20, 1905, shall be constructive notice of the registrant's claim of ownership thereof."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1072?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1072. Registration as constructive notice of claim of ownership","tname":"Commerce and Trade","by":{"0":"3"}},{"t":"usc","label":"15 U.S.C. § 1114","url":"https://www.law.cornell.edu/uscode/text/15/1114","subs":["(1)(a)","(1)(b)"],"stext":{"head":"§1114. Remedies; infringement; innocent infringement by printers and publishers","paras":[[0,"(1) Any person who shall, without the consent of the registrant—"],[1,"(a) use in commerce any reproduction, counterfeit, copy, or colorable imitation of a registered mark in connection with the sale, offering for sale, distribution, or advertising of any goods or services on or in connection with which such use is likely to cause confusion, or to cause mistake, or to deceive; or"],[1,"(b) reproduce, counterfeit, copy, or colorably imitate a registered mark and apply such reproduction, counterfeit, copy, or colorable imitation to labels, signs, prints, packages, wrappers, receptacles or advertisements intended to be used in commerce upon or in connection with the sale, offering for sale, distribution, or advertising of goods or services on or in connection with which such use is likely to cause confusion, or to cause mistake, or to deceive,"],[0,"shall be liable in a civil action by the registrant for the remedies hereinafter provided. Under subsection (b) hereof, the registrant shall not be entitled to recover profits or damages unless the acts have been committed with knowledge that such imitation is intended to be used to cause confusion, or to cause mistake, or to deceive."],[0,"As used in this paragraph, the term \"any person\" includes the United States, all agencies and instrumentalities thereof, and all individuals, firms, corporations, or other persons acting for the United States and with the authorization and consent of the United States, and any State, any instrumentality of a State, and any officer or employee of a State or instrumentality of a State acting in his or her official capacity. The United States, all agencies and instrumentalities thereof, and all individuals, firms, corporations, other persons acting for the United States and with the authorization and consent of the United States, and any State, and any such instrumentality, officer, or employee, shall be subject to the provisions of this chapter in the same manner and to the same extent as any nongovernmental entity."],[0,"(2) Notwithstanding any other provision of this chapter, the remedies given to the owner of a right infringed under this chapter or to a person bringing an action under section 1125(a) or (d) of this title shall be limited as follows:"],[1,"(A) Where an infringer or violator is engaged solely in the business of printing the mark or violating matter for others and establishes that he or she was an innocent infringer or innocent violator, the owner of the right infringed or person bringing the action under section 1125(a) of this title shall be entitled as against such infringer or violator only to an injunction against future printing."],[1,"(B) Where the infringement or violation complained of is contained in or is part of paid advertising matter in a newspaper, magazine, or other similar periodical or in an electronic communication as defined in section 2510(12) of title 18, the remedies of the owner of the right infringed or person bringing the action under section 1125(a) of this title as against the publisher or distributor of such newspaper, magazine, or other similar periodical or electronic communication shall be limited to an injunction against the presentation of such advertising matter in future issues of such newspapers, magazines, or other similar periodicals or in future transmissions of such electronic communications. The limitations of this subparagraph shall apply only to innocent infringers and innocent violators."],[1,"(C) Injunctive relief shall not be available to the owner of the right infringed or person bringing the action under section 1125(a) of this title with respect to an issue of a newspaper, magazine, or other similar periodical or an electronic communication containing infringing matter or violating matter where restraining the dissemination of such infringing matter or violating matter in any particular issue of such periodical or in an electronic communication would delay the delivery of such issue or transmission of such electronic communication after the regular time for such delivery or transmission, and such delay would be due to the method by which publication and distribution of such periodical or transmission of such electronic communication is customarily conducted in accordance with sound business practice, and not due to any method or device adopted to evade this section or to prevent or delay the issuance of an injunction or restraining order with respect to such infringing matter or violating matter."],[1,"(D)(i)(I) A domain name registrar, a domain name registry, or other domain name registration authority that takes any action described under clause (ii) affecting a domain name shall not be liable for monetary relief or, except as provided in subclause (II), for injunctive relief, to any person for such action, regardless of whether the domain name is finally determined to infringe or dilute the mark."],[1,"(II) A domain name registrar, domain name registry, or other domain name registration authority described in subclause (I) may be subject to injunctive relief only if such registrar, registry, or other registration authority has—"],[2,"(aa) not expeditiously deposited with a court, in which an action has been filed regarding the disposition of the domain name, documents sufficient for the court to establish the court's control and authority regarding the disposition of the registration and use of the domain name;"],[2,"(bb) transferred, suspended, or otherwise modified the domain name during the pendency of the action, except upon order of the court; or"],[2,"(cc) willfully failed to comply with any such court order."],[1,"(ii) An action referred to under clause (i)(I) is any action of refusing to register, removing from registration, transferring, temporarily disabling, or permanently canceling a domain name—"],[2,"(I) in compliance with a court order under section 1125(d) of this title; or"],[2,"(II) in the implementation of a reasonable policy by such registrar, registry, or authority prohibiting the registration of a domain name that is identical to, confusingly similar to, or dilutive of another's mark."],[1,"(iii) A domain name registrar, a domain name registry, or other domain name registration authority shall not be liable for damages under this section for the registration or maintenance of a domain name for another absent a showing of bad faith intent to profit from such registration or maintenance of the domain name."],[1,"(iv) If a registrar, registry, or other registration authority takes an action described under clause (ii) based on a knowing and material misrepresentation by any other person that a domain name is identical to, confusingly similar to, or dilutive of a mark, the person making the knowing and material misrepresentation shall be liable for any damages, including costs and attorney's fees, incurred by the domain name registrant as a result of such action. The court may also grant injunctive relief to the domain name registrant, including the reactivation of the domain name or the transfer of the domain name to the domain name registrant."],[1,"(v) A domain name registrant whose domain name has been suspended, disabled, or transferred under a policy described under clause (ii)(II) may, upon notice to the mark owner, file a civil action to establish that the registration or use of the domain name by such registrant is not unlawful under this chapter. The court may grant injunctive relief to the domain name registrant, including the reactivation of the domain name or transfer of the domain name to the domain name registrant."],[1,"(E) As used in this paragraph—"],[2,"(i) the term \"violator\" means a person who violates section 1125(a) of this title; and"],[2,"(ii) the term \"violating matter\" means matter that is the subject of a violation under section 1125(a) of this title."],[0,"(3)(A) Any person who engages in the conduct described in paragraph (11) of section 110 of title 17 and who complies with the requirements set forth in that paragraph is not liable on account of such conduct for a violation of any right under this chapter. This subparagraph does not preclude liability, nor shall it be construed to restrict the defenses or limitations on rights granted under this chapter, of a person for conduct not described in paragraph (11) of section 110 of title 17, even if that person also engages in conduct described in paragraph (11) of section 110 of such title."],[0,"(B) A manufacturer, licensee, or licensor of technology that enables the making of limited portions of audio or video content of a motion picture imperceptible as described in subparagraph (A) is not liable on account of such manufacture or license for a violation of any right under this chapter, if such manufacturer, licensee, or licensor ensures that the technology provides a clear and conspicuous notice at the beginning of each performance that the performance of the motion picture is altered from the performance intended by the director or copyright holder of the motion picture. The limitations on liability in subparagraph (A) and this subparagraph shall not apply to a manufacturer, licensee, or licensor of technology that fails to comply with this paragraph."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1114?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1114. Remedies; infringement; innocent infringement by printers and publishers","tname":"Commerce and Trade","by":{"0":"20, 2, 2"}},{"t":"usc","label":"15 U.S.C. § 1115","url":"https://www.law.cornell.edu/uscode/text/15/1115","subs":["(a)","(b)"],"stext":{"head":"§1115. Registration on principal register as evidence of exclusive right to use mark; defenses","paras":[[0,"(a) Evidentiary value; defenses"],[0,"Any registration issued under the Act of March 3, 1881, or the Act of February 20, 1905, or of a mark registered on the principal register provided by this chapter and owned by a party to an action shall be admissible in evidence and shall be prima facie evidence of the validity of the registered mark and of the registration of the mark, of the registrant's ownership of the mark, and of the registrant's exclusive right to use the registered mark in commerce on or in connection with the goods or services specified in the registration subject to any conditions or limitations stated therein, but shall not preclude another person from proving any legal or equitable defense or defect, including those set forth in subsection (b), which might have been asserted if such mark had not been registered."],[0,"(b) Incontestability; defenses"],[0,"To the extent that the right to use the registered mark has become incontestable under section 1065 of this title, the registration shall be conclusive evidence of the validity of the registered mark and of the registration of the mark, of the registrant's ownership of the mark, and of the registrant's exclusive right to use the registered mark in commerce. Such conclusive evidence shall relate to the exclusive right to use the mark on or in connection with the goods or services specified in the affidavit filed under the provisions of section 1065 of this title, or in the renewal application filed under the provisions of section 1059 of this title if the goods or services specified in the renewal are fewer in number, subject to any conditions or limitations in the registration or in such affidavit or renewal application. Such conclusive evidence of the right to use the registered mark shall be subject to proof of infringement as defined in section 1114 of this title, and shall be subject to the following defenses or defects:"],[1,"(1) That the registration or the incontestable right to use the mark was obtained fraudulently; or"],[1,"(2) That the mark has been abandoned by the registrant; or"],[1,"(3) That the registered mark is being used by or with the permission of the registrant or a person in privity with the registrant, so as to misrepresent the source of the goods or services on or in connection with which the mark is used; or"],[1,"(4) That the use of the name, term, or device charged to be an infringement is a use, otherwise than as a mark, of the party's individual name in his own business, or of the individual name of anyone in privity with such party, or of a term or device which is descriptive of and used fairly and in good faith only to describe the goods or services of such party, or their geographic origin; or"],[1,"(5) That the mark whose use by a party is charged as an infringement was adopted without knowledge of the registrant's prior use and has been continuously used by such party or those in privity with him from a date prior to (A) the date of constructive use of the mark established pursuant to section 1057(c) of this title, (B) the registration of the mark under this chapter if the application for registration is filed before the effective date of the Trademark Law Revision Act of 1988, or (C) publication of the registered mark under subsection (c) of section 1062 of this title: Provided, however, That this defense or defect shall apply only for the area in which such continuous prior use is proved; or"],[1,"(6) That the mark whose use is charged as an infringement was registered and used prior to the registration under this chapter or publication under subsection (c) of section 1062 of this title of the registered mark of the registrant, and not abandoned: Provided, however, That this defense or defect shall apply only for the area in which the mark was used prior to such registration or such publication of the registrant's mark; or"],[1,"(7) That the mark has been or is being used to violate the antitrust laws of the United States; or"],[1,"(8) That the mark is functional; or"],[1,"(9) That equitable principles, including laches, estoppel, and acquiescence, are applicable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1115?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1115. Registration on principal register as evidence of exclusive right to use mark; defenses","tname":"Commerce and Trade","by":{"0":"2, 2"}},{"t":"usc","label":"15 U.S.C. § 1125","url":"https://www.law.cornell.edu/uscode/text/15/1125","subs":["(a)(1)(A)"],"by":{"0":"2"}},{"t":"usc","label":"35 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/35/2","subs":["(a)(1)"],"stext":{"head":"§2. Powers and duties","paras":[[0,"(a) In General.—The United States Patent and Trademark Office, subject to the policy direction of the Secretary of Commerce—"],[1,"(1) shall be responsible for the granting and issuing of patents and the registration of trademarks; and"],[1,"(2) shall be responsible for disseminating to the public information with respect to patents and trademarks."],[0,"(b) Specific Powers.—The Office—"],[1,"(1) shall adopt and use a seal of the Office, which shall be judicially noticed and with which letters patent, certificates of trademark registrations, and papers issued by the Office shall be authenticated;"],[1,"(2) may establish regulations, not inconsistent with law, which—"],[2,"(A) shall govern the conduct of proceedings in the Office;"],[2,"(B) shall be made in accordance with section 553 of title 5;"],[2,"(C) shall facilitate and expedite the processing of patent applications, particularly those which can be filed, stored, processed, searched, and retrieved electronically, subject to the provisions of section 122 relating to the confidential status of applications;"],[2,"(D) may govern the recognition and conduct of agents, attorneys, or other persons representing applicants or other parties before the Office, and may require them, before being recognized as representatives of applicants or other persons, to show that they are of good moral character and reputation and are possessed of the necessary qualifications to render to applicants or other persons valuable service, advice, and assistance in the presentation or prosecution of their applications or other business before the Office;"],[2,"(E) shall recognize the public interest in continuing to safeguard broad access to the United States patent system through the reduced fee structure for small entities under section 41(h)(1);"],[2,"(F) provide for the development of a performance-based process that includes quantitative and qualitative measures and standards for evaluating cost-effectiveness and is consistent with the principles of impartiality and competitiveness; and"],[2,"(G) may, subject to any conditions prescribed by the Director and at the request of the patent applicant, provide for prioritization of examination of applications for products, processes, or technologies that are important to the national economy or national competitiveness without recovering the aggregate extra cost of providing such prioritization, notwithstanding section 41 or any other provision of law;"],[1,"(3) may acquire, construct, purchase, lease, hold, manage, operate, improve, alter, and renovate any real, personal, or mixed property, or any interest therein, as it considers necessary to carry out its functions;"],[1,"(4)(A) may make such purchases, contracts for the construction, maintenance, or management and operation of facilities, and contracts for supplies or services, without regard to the provisions of subtitle I and chapter 33 of title 40, division C (except sections 3302, 3501(b), 3509, 3906, 4710, and 4711) of subtitle I of title 41, and the McKinney-Vento Homeless Assistance Act (42 U.S.C. 11301 et seq.); and"],[1,"(B) may enter into and perform such purchases and contracts for printing services, including the process of composition, platemaking, presswork, silk screen processes, binding, microform, and the products of such processes, as it considers necessary to carry out the functions of the Office, without regard to sections 501 through 517 and 1101 through 1123 of title 44;"],[1,"(5) may use, with their consent, services, equipment, personnel, and facilities of other departments, agencies, and instrumentalities of the Federal Government, on a reimbursable basis, and cooperate with such other departments, agencies, and instrumentalities in the establishment and use of services, equipment, and facilities of the Office;"],[1,"(6) may, when the Director determines that it is practicable, efficient, and cost-effective to do so, use, with the consent of the United States and the agency, instrumentality, Patent and Trademark Office, or international organization concerned, the services, records, facilities, or personnel of any State or local government agency or instrumentality or foreign patent and trademark office or international organization to perform functions on its behalf;"],[1,"(7) may retain and use all of its revenues and receipts, including revenues from the sale, lease, or disposal of any real, personal, or mixed property, or any interest therein, of the Office;"],[1,"(8) shall advise the President, through the Secretary of Commerce, on national and certain international intellectual property policy issues;"],[1,"(9) shall advise Federal departments and agencies on matters of intellectual property policy in the United States and intellectual property protection in other countries;"],[1,"(10) shall provide guidance, as appropriate, with respect to proposals by agencies to assist foreign governments and international intergovernmental organizations on matters of intellectual property protection;"],[1,"(11) may conduct programs, studies, or exchanges of items or services regarding domestic and international intellectual property law and the effectiveness of intellectual property protection domestically and throughout the world, and the Office is authorized to expend funds to cover the subsistence expenses and travel-related expenses, including per diem, lodging costs, and transportation costs, of persons attending such programs who are not Federal employees;"],[1,"(12)(A) shall advise the Secretary of Commerce on programs and studies relating to intellectual property policy that are conducted, or authorized to be conducted, cooperatively with foreign intellectual property offices and international intergovernmental organizations; and"],[1,"(B) may conduct programs and studies described in subparagraph (A); and"],[1,"(13)(A) in coordination with the Department of State, may conduct programs and studies cooperatively with foreign intellectual property offices and international intergovernmental organizations; and"],[1,"(B) with the concurrence of the Secretary of State, may authorize the transfer of not to exceed $100,000 in any year to the Department of State for the purpose of making special payments to international intergovernmental organizations for studies and programs for advancing international cooperation concerning patents, trademarks, and other matters."],[0,"(c) Clarification of Specific Powers.—(1) The special payments under subsection (b)(13)(B) shall be in addition to any other payments or contributions to international organizations described in subsection (b)(13)(B) and shall not be subject to any limitations imposed by law on the amounts of such other payments or contributions by the United States Government."],[0,"(2) Nothing in subsection (b) shall derogate from the duties of the Secretary of State or from the duties of the United States Trade Representative as set forth in section 141 of the Trade Act of 1974 (19 U.S.C. 2171)."],[0,"(3) Nothing in subsection (b) shall derogate from the duties and functions of the Register of Copyrights or otherwise alter current authorities relating to copyright matters."],[0,"(4) In exercising the Director's powers under paragraphs (3) and (4)(A) of subsection (b), the Director shall consult with the Administrator of General Services."],[0,"(5) In exercising the Director's powers and duties under this section, the Director shall consult with the Register of Copyrights on all copyright and related matters."],[0,"(d) Construction.—Nothing in this section shall be construed to nullify, void, cancel, or interrupt any pending request-for-proposal let or contract issued by the General Services Administration for the specific purpose of relocating or leasing space to the United States Patent and Trademark Office."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/2?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§2. Powers and duties","tname":"Patents","by":{"0":"2"}}]};